draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // mushroom cap
  ctx.fillStyle = '#964B00';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // mushroom stem
  ctx.fillStyle = '#786C3B';
  ctx.beginPath();
  ctx.rect(W/2-5, H/2+50, 10, 50 + 20*Math.cos(t));
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2-100, H/2-50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2-30);
  ctx.lineTo(W/2-100, H/2+20);
  ctx.lineTo(W/2-90, H/2+50);
  ctx.lineTo(W/2-110, H/2+50);
  ctx.lineTo(W/2-100, H/2+20);
  ctx.stroke();

  // protein text
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Protein:', W/2-150, H/2-100);
  ctx.fillText('Fungi', W/2-150, H/2-70);
  ctx.fillText('Not Plant', W/2-150, H/2-40);

  ctx.restore();
}
